  assert.equal(lowerBound([1, 3, 5, 7, 9], 5), 2);
  assert.equal(upperBound([1, 3, 5, 7, 9], 5), 3);
});

test('a value between two elements', () => {
  assert.equal(lowerBound([1, 3, 5, 7, 9], 4), 2);
  assert.equal(upperBound([1, 3, 5, 7, 9], 4), 2);
});

test('edge cases and duplicates', () => {
  const arr = [1, 2, 2, 2, 4, 6];
  assert.equal(lowerBound(arr, 2), 1);
  assert.equal(upperBound(arr, 2), 4);
  assert.equal(upperBound(arr, 2) - lowerBound(arr, 2), 3);

  assert.equal(lowerBound(arr, 0), 0);
  assert.equal(upperBound(arr, 0), 0);

  assert.equal(lowerBound(arr, 7), 6);
  assert.equal(upperBound(arr, 7), 6);

  assert.equal(lowerBound([], 1), 0);
  assert.equal(upperBound([], 1), 0);
});

test('type validation', () => {
  assert.throws(() => lowerBound('not an array', 1), TypeError);
  assert.throws(() => upperBound('not an array', 1), TypeError);
  assert.throws(() => lowerBound([1, 2, 3], '1'), TypeError);
  assert.throws(() => upperBound([1, 2, 3], NaN), TypeError);
});
